import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class GoodFileServlet extends HttpServlet {
    private static final Path DATA_ROOT = Paths.get("/var/data").toAbsolutePath().normalize();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String fileName = req.getParameter("file");

        // Fix: do not invoke a shell; use the Java NIO API and validate the resolved path
        if (fileName == null || fileName.isEmpty()) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        Path resolved = DATA_ROOT.resolve(fileName).normalize();
        if (!resolved.startsWith(DATA_ROOT)) {
            resp.sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        if (!Files.isRegularFile(resolved)) {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        String content = new String(Files.readAllBytes(resolved), StandardCharsets.UTF_8);
        resp.setContentType("text/plain");
        resp.getWriter().write(content);
    }
}

