import java.io.IOException;
import java.util.Arrays;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class GoodServlet extends HttpServlet {
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String host = request.getParameter("host");

        // Safe: validate input and pass it as a discrete argument without invoking a shell.
        if (host == null || !host.matches("^[a-zA-Z0-9]([a-zA-Z0-9.-]{0,252})?$")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid host");
            return;
        }

        String[] command = {"ping", "-c", "1", host};
        ProcessBuilder processBuilder = new ProcessBuilder(Arrays.asList(command));
        processBuilder.redirectErrorStream(true);
        processBuilder.start();

        response.getWriter().write("Ping requested");
    }
}
