{
  "rubric_name": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "description": "A structured rubric for evaluating the performance of a software engineer across technical, delivery, and collaboration dimensions. Reviewers should assign a score for each criterion, provide evidence, and align ratings to the defined anchors.",
  "rating_scale": {
    "minimum_score": 1,
    "maximum_score": 5,
    "levels": [
      {
        "score": 1,
        "label": "Significant Development Needed",
        "descriptor": "Consistently falls below expectations and requires frequent guidance, remediation, or close supervision."
      },
      {
        "score": 2,
        "label": "Developing",
        "descriptor": "Shows some expected capability but requires regular support, correction, or limited scope to succeed."
      },
      {
        "score": 3,
        "label": "Meets Expectations",
        "descriptor": "Reliably performs the core responsibilities of the role with appropriate independence, quality, and impact."
      },
      {
        "score": 4,
        "label": "Exceeds Expectations",
        "descriptor": "Consistently exceeds role expectations through higher-quality output, greater autonomy, or meaningful positive impact on the team or product."
      },
      {
        "score": 5,
        "label": "Role Model",
        "descriptor": "Sets a benchmark for the organization through exceptional impact, influence, technical excellence, and sustained high performance."
      }
    ]
  },
  "criteria": [
    {
      "id": "TECH",
      "name": "Technical Proficiency",
      "weight": 0.2,
      "description": "Depth and application of engineering knowledge, including language proficiency, architecture, algorithms, data structures, system design, and domain knowledge.",
      "assessment_questions": [
        "Can the engineer independently design and implement technically sound solutions?",
        "Do they demonstrate appropriate understanding of trade-offs, complexity, and scalability?",
        "Can they explain technical decisions clearly and defend them with evidence?"
      ],
      "behavior_anchors": {
        "1": "Requires frequent technical guidance and often selects or implements suboptimal approaches.",
        "3": "Applies solid technical knowledge to solve most assigned problems with appropriate trade-offs and occasional support.",
        "5": "Demonstrates expert-level technical judgment, designs robust systems, and elevates technical decisions across the team."
      }
    },
    {
      "id": "CODE",
      "name": "Code Quality",
      "weight": 0.2,
      "description": "Produces readable, maintainable, testable code that follows team standards and minimizes rework.",
      "assessment_questions": [
        "Is code clear, modular, and maintainable?",
        "Are unit tests, integration tests, and CI practices appropriate and meaningful?",
        "Do pull requests reflect thoughtful review, iteration, and quality standards?"
      ],
      "behavior_anchors": {
        "1": "Code is difficult to understand, maintain, or extend and often introduces avoidable defects.",
        "3": "Code is clear and maintainable, with appropriate tests and review hygiene.",
        "5": "Sets high standards for maintainability, writes exemplary tests, and proactively improves team code quality."
      }
    },
    {
      "id": "PROBLEM",
      "name": "Problem Solving",
      "weight": 0.15,
      "description": "Diagnoses, analyzes, and resolves technical issues using systematic reasoning and appropriate tools.",
      "assessment_questions": [
        "Do they identify root causes rather than only symptoms?",
        "Do they break down ambiguous problems into manageable steps?",
        "Do they validate hypotheses with data, logs, experiments, or test cases?"
      ],
      "behavior_anchors": {
        "1": "Relies on trial-and-error and needs significant support to isolate issues.",
        "3": "Systematically diagnoses common and moderately complex issues with sound reasoning.",
        "5": "Rapidly resolves ambiguous or high-impact issues, identifies systemic causes, and prevents recurrence."
      }
    },
    {
      "id": "DELIVERY",
      "name": "Delivery and Reliability",
      "weight": 0.15,
      "description": "Meets commitments, maintains quality, and supports stable production outcomes.",
      "assessment_questions": [
        "Are estimates realistic and progress visible?",
        "Is work released with appropriate quality, monitoring, and rollback plans?",
        "How do they respond to incidents, regressions, or production risks?"
      ],
      "behavior_anchors": {
        "1": "Frequently misses commitments or delivers work that causes avoidable production instability.",
        "3": "Delivers work predictably with acceptable quality and supports production reliability.",
        "5": "Consistently exceeds reliability expectations, reduces risk through strong observability, and improves team delivery predictability."
      }
    },
    {
      "id": "COLLAB",
      "name": "Collaboration and Communication",
      "weight": 0.15,
      "description": "Works effectively with peers, stakeholders, and cross-functional partners.",
      "assessment_questions": [
        "Do they communicate progress, risks, and technical constraints clearly?",
        "Are they responsive, respectful, and constructive in reviews, standups, and meetings?",
        "Do they share knowledge and support team alignment?"
      ],
      "behavior_anchors": {
        "1": "Communication is infrequent, unclear, or unconstructive, creating avoidable friction.",
        "3": "Collaborates effectively and communicates status and risks in a timely, professional manner.",
        "5": "Acts as a collaborative force multiplier, strengthens team communication, and bridges technical and non-technical audiences."
      }
    },
    {
      "id": "OWNERSHIP",
      "name": "Ownership and Business Impact",
      "weight": 0.1,
      "description": "Drives work end-to-end and connects engineering output to product and business outcomes.",
      "assessment_questions": [
        "Do they take accountability beyond narrow task assignment?",
        "Do they identify improvements that benefit users, cost, performance, or strategy?",
        "Can they prioritize work based on impact and urgency?"
      ],
      "behavior_anchors": {
        "1": "Completes narrow tasks and rarely considers broader product or business impact.",
        "3": "Owns assigned work end-to-end and contributes to team goals with clear outcomes.",
        "5": "Consistently identifies high-impact opportunities, drives cross-functional initiatives, and delivers measurable business value."
      }
    },
    {
      "id": "GROWTH",
      "name": "Learning and Adaptability",
      "weight": 0.05,
      "description": "Continuously improves skills, embraces feedback, and adapts to changing requirements or technologies.",
      "assessment_questions": [
        "Do they seek and apply feedback effectively?",
        "Do they learn new tools, frameworks, or domains as needed?",
        "Do they adapt their approach when requirements or context change?"
      ],
      "behavior_anchors": {
        "1": "Resists new approaches and struggles to apply feedback or learn from experience.",
        "3": "Learns from feedback, improves over time, and adapts to moderate changes in scope or technology.",
        "5": "Proactively acquires new skills, shares learnings, and rapidly adapts to evolving product or technical contexts."
      }
    }
  ],
  "role_alignment": {
    "junior_engineer": [
      "Completes well-defined tasks under guidance.",
      "Follows existing patterns and asks for review when blocked.",
      "Builds strong fundamentals and produces reliable, tested code."
    ],
    "mid_engineer": [
      "Independently delivers features and fixes complex issues.",
      "Contributes to design discussions and improves code quality.",
      "Communicates risks, progress, and technical rationale effectively."
    ],
    "senior_engineer": [
      "Drives technical direction and solves ambiguous, cross-system problems.",
      "Mentors others, sets standards, and unblocks the team.",
      "Links engineering work to product and business outcomes."
    ]
  },
  "scoring_and_evidence": {
    "overall_score_method": "Weighted average of criterion scores, rounded to one decimal place.",
    "evidence_requirements": [
      "Provide at least two concrete examples for each criterion.",
      "Reference specific work artifacts, projects, incidents, or measurable outcomes where possible.",
      "Include both strengths and development opportunities with actionable next steps."
    ]
  },
  "development_plan_template": {
    "growth_goals": [
      "Define 2 to 3 measurable improvement goals.",
      "Identify the skill, behavior, or impact area targeted by each goal.",
      "Set a review checkpoint date for progress assessment."
    ],
    "success_metrics": [
      "Define observable or measurable indicators of progress.",
      "Link metrics to role expectations and business outcomes where possible.",
      "Agree on how success will be evaluated at the next review."
    ],
    "support_from_manager": [
      "Identify mentoring, training, or stretch assignments needed.",
      "Define feedback cadence and accountability checkpoints.",
      "Clarify any blockers or resources required for growth."
    ]
  },
  "reviewer_guidance": [
    "Evaluate evidence-based performance, not personality or style preferences.",
    "Consider role level, time in role, and goals established at the beginning of the review period.",
    "Frame feedback around observable behaviors, impact, and future improvement.",
    "Balance recognition of strengths with clear, actionable development expectations."
  ]
}

