{
  "startup_name": "Tipperary",
  "tagline": "Know what to tip before you sit down.",
  "pitch": {
    "executive_summary": "Tipperary is a mobile app that helps people find the average tip size for each restaurant. By combining public dining data, user-submitted tip insights, and payment signals, Tipperary gives diners a clear, local benchmark for tipping while giving restaurants a practical way to understand tip behavior and service expectations.",
    "problem": {
      "core_pain": "People often feel uncertain about how much to tip at restaurants, especially when visiting new areas, trying new price points, or comparing different service experiences.",
      "pain_points": [
        "Tip expectations vary widely by city, cuisine, price range, and service style.",
        "Customers may under-tip because they do not know the local norm.",
        "Restaurants and staff may receive inconsistent tips due to customer uncertainty.",
        "Service workers in tip-dependent roles benefit from more predictable and consistent tipping behavior."
      ]
    },
    "solution": {
      "description": "Tipperary shows the average tip size for each restaurant in a simple, transparent format, so users can make faster and more confident tipping decisions.",
      "core_features": [
        "Restaurant profile pages showing average tip percentage and typical dollar range",
        "Benchmarks by city, cuisine, price point, and service type",
        "Trend labels such as 'higher than local average' or 'below area median'",
        "Anonymous user-submitted tip data with optional verification",
        "Restaurant dashboard showing tip benchmarks and service performance trends",
        "Payment-integration layer that can suggest a tip amount before checkout"
      ]
    },
    "target_market": {
      "primary_users": [
        "Urban diners using mobile payments and digital wallets",
        "Frequent restaurant patrons, travelers, and first-time diners",
        "Restaurants, bars, and hospitality brands seeking customer-service insights"
      ],
      "why_now": "Digital tipping is already built into cards, POS systems, delivery apps, and mobile wallets. Tipperary adds a simple decision layer on top of an existing high-frequency behavior."
    },
    "go_to_market": {
      "consumer_strategy": [
        "Launch in dense metro areas with strong dining scenes",
        "Partner with local food creators, review platforms, and city guides",
        "Create shareable tip benchmark cards for restaurants and diners",
        "Integrate with payment and POS providers to appear at the moment of checkout"
      ],
      "restaurant_strategy": [
        "Offer a free basic dashboard for restaurants to see average tip size",
        "Provide premium analytics for multi-location hospitality brands",
        "Incentivize data quality through optional staff and customer submissions",
        "Position Tipperary as a service-experience and revenue-clarity tool"
      ]
    },
    "business_model": {
      "revenue_streams": [
        "SaaS subscription for restaurants and hospitality groups",
        "API licensing to payment, POS, and hospitality software vendors",
        "Premium consumer features such as travel mode and personalized tip alerts",
        "Sponsored benchmarking and partnerships with clear disclosure"
      ],
      "monetization_logic": "The consumer app builds usage and data, while the restaurant and platform side monetizes the improved visibility, service insight, and tip predictability."
    },
    "competitive_advantages": [
      "Focused data asset: restaurant-level average tip size, not generic reviews",
      "Continuous data loop: every payment and submission improves accuracy",
      "Local normalization makes comparisons fair across cities and cuisines",
      "Network effects: more restaurants covered makes the app more useful, which generates more data"
    ],
    "key_metrics": [
      "Average tip accuracy confidence by restaurant and region",
      "Weekly active users submitting tip data",
      "Restaurant dashboard engagement and retention",
      "Tip suggestion adoption rate at checkout",
      "Partner API calls and integration volume"
    ],
    "roadmap": [
      {
        "phase": "Pilot",
        "timeline": "0 to 6 months",
        "goals": [
          "Launch in two major metro markets",
          "Build the first data model for average tip size",
          "Recruit 100 pilot restaurants and 50,000 active users"
        ]
      },
      {
        "phase": "Scale",
        "timeline": "6 to 18 months",
        "goals": [
          "Expand into 10 metro markets",
          "Integrate with two POS or payment partners",
          "Launch the restaurant analytics subscription"
        ]
      },
      {
        "phase": "Monetize",
        "timeline": "18 to 36 months",
        "goals": [
          "Generate recurring B2B revenue from multi-location hospitality brands",
          "Offer a tipping-benchmark API to software partners",
          "Introduce premium consumer plans"
        ]
      }
    ],
    "risk_and_mitigation": {
      "risks": [
        "Data may be sparse for smaller or new restaurants",
        "Tip behavior may vary by time of day, party size, and service quality",
        "Restaurants may be hesitant to display public benchmarks"
      ],
      "mitigation": [
        "Use confidence scores and show benchmarks only when data is sufficient",
        "Normalize by price point, cuisine, region, and service type",
        "Offer restaurants private dashboards first, with public display as an optional feature"
      ]
    },
    "ask": {
      "funding": "Seeking seed capital to build the product, data infrastructure, partnerships, and early go-to-market engine.",
      "use_of_funds": {
        "engineering_and_product": "45%",
        "data_and_ai": "25%",
        "go_to_market_and_partnerships": "20%",
        "operations": "10%"
      },
      "milestones": [
        "12 months: 10 metro markets, 250,000 monthly active users, 1,000 active restaurant dashboards",
        "18 months: two paid B2B partnerships and first 1 million dollars in annual recurring revenue",
        "24 months: defensible data network covering 25% of targeted dining venues in covered metros"
      ]
    }
  }
}

