Here's the page — **The Bill Book**, a vintage chapbook of 25 limericks about various Bills, complete with a working "Draw a Bill" lottery, a scrollspy index, scansion demo, and all three required keywords woven into the verses and errata.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>The Bill Book — Twenty-Five Limericks Concerning Persons Named Bill</title>
<meta name="description" content="A chapbook of twenty-five limericks concerning persons of the name of bill — one an economist, one a dinner guest of a jurgen from the Rhineland.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Rye&family=IM+Fell+English:ital@0;1&family=Spectral:ital,wght@0,300;0,400;0,500;0,600;1,400;1,500&display=swap" rel="stylesheet">
<style>
:root{
  --paper:#f2ead6; --paper2:#faf4e4; --ink:#221a10; --ink-soft:#5c5140;
  --madder:#8c2b1b; --gold:#b3892f; --line:rgba(34,26,16,.28);
  --disp:'Rye',serif; --serif:'IM Fell English',serif; --body:'Spectral',serif;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  background:var(--paper); color:var(--ink); font-family:var(--body);
  font-size:16px; line-height:1.6; overflow-x:hidden;
}
body::before{
  content:""; position:fixed; inset:0; z-index:0; pointer-events:none;
  background:
    radial-gradient(1100px 700px at 18% -8%, rgba(255,250,232,.9), transparent 60%),
    radial-gradient(900px 700px at 108% 28%, rgba(140,43,27,.06), transparent 55%),
    radial-gradient(1000px 800px at 50% 115%, rgba(34,26,16,.08), transparent 60%);
}
::selection{background:var(--madder);color:var(--paper)}
.grain{
  position:fixed; inset:0; z-index:80; pointer-events:none; opacity:.055; mix-blend-mode:multiply;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/></filter><rect width='240' height='240' filter='url(%23n)' opacity='0.7'/></svg>");
}
.inkbar{position:fixed;top:0;left:0;height:4px;width:0;background:var(--madder);z-index:100}

/* ---------- masthead ---------- */
.masthead{position:relative;z-index:1;padding:0 20px}
.mast-band{
  display:flex;justify-content:space-between;align-items:center;gap:1rem;
  padding:15px 2px; border-bottom:1px solid var(--line);
  font-size:.66rem; letter-spacing:.24em; text-transform:uppercase; font-weight:600; color:var(--ink-soft);
}
.mast-band .b-mid{flex:1;text-align:center; font-weight:400; letter-spacing:.3em}
.mast-frame{
  position:relative; max-width:920px; margin:46px auto 0;
  border:1px solid var(--ink); padding:clamp(2.6rem,6vw,4.4rem) 1.4rem clamp(2.2rem,5vw,3.4rem);
  background:var(--paper2); animation:press .6s cubic-bezier(.2,.8,.3,1.1) both;
}
.mast-frame::before{content:"";position:absolute;inset:8px;border:1px solid var(--line);pointer-events:none}
.corner{position:absolute;color:var(--madder);font-size:1rem;line-height:1;z-index:2}
.c-tl{top:12px;left:14px}.c-tr{top:12px;right:14px}.c-bl{bottom:12px;left:14px}.c-br{bottom:12px;right:14px}
@keyframes press{from{transform:scale(1.025);opacity:.35}to{transform:none;opacity:1}}
.mast-kicker{text-align:center;letter-spacing:.34em;text-transform:uppercase;font-size:.68rem;font-weight:600;color:var(--madder)}
#mastTitle{
  font-family:var(--disp); font-weight:400; text-align:center;
  font-size:clamp(3rem,10vw,6.6rem); line-height:1.05; margin:.3em 0 .05em; letter-spacing:.02em;
}
#mastTitle .ltr{display:inline-block;animation:letter-in .7s cubic-bezier(.2,.8,.3,1.18) both;animation-delay:var(--d,0s)}
#mastTitle .ltr.sp{width:.42em}
@keyframes letter-in{
  0%{opacity:0;transform:translateY(-.65em) rotate(7deg) scale(1.06)}
  60%{opacity:1;transform:translateY(.05em) rotate(-1.5deg)}
  100%{opacity:1;transform:none}
}
.mast-rule{display:flex;align-items:center;gap:14px;max-width:400px;margin:16px auto}
.mast-rule::before,.mast-rule::after{content:"";flex:1;height:1px;background:var(--ink);opacity:.55}
.mast-rule span{color:var(--madder)}
.mast-sub{
  font-family:var(--serif);font-style:italic;text-align:center;
  font-size:clamp(1.02rem,2.2vw,1.28rem);max-width:46ch;margin:0 auto;color:var(--ink-soft);
}
.mast-meta{margin-top:24px;text-align:center;font-size:.64rem;letter-spacing:.24em;text-transform:uppercase;font-weight:600;color:var(--ink-soft)}
.mast-meta b{color:var(--madder);font-weight:600}
.stamp{position:absolute;top:26px;right:26px;width:112px;height:112px;color:var(--madder);opacity:.85;animation:spin 30s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

/* ---------- ticker ---------- */
.ticker{margin-top:46px;background:var(--ink);color:var(--paper);border-block:1px solid var(--ink);overflow:hidden;padding:11px 0;position:relative;z-index:1}
.ticker-track{display:flex;width:max-content;animation:tick 48s linear infinite}
.ticker:hover .ticker-track{animation-play-state:paused}
@keyframes tick{to{transform:translateX(-50%)}}
.tgroup{display:flex;align-items:center;gap:2.4rem;padding-right:2.4rem;white-space:nowrap;font-size:.7rem;letter-spacing:.28em;font-weight:600;text-transform:uppercase}
.tgroup b{color:var(--gold);font-weight:400}

/* ---------- sheet ---------- */
.sheet{position:relative;z-index:1;max-width:1160px;margin:0 auto;padding:0 24px 90px}
.sec{position:relative;margin:clamp(3rem,7vw,4.6rem) 0 1.4rem}
.sec::before{content:"";display:flex;align-items:center;gap:12px;margin-bottom:1.3rem}
.sec::before::before,.sec::before::after{content:"";flex:1;height:1px;background:var(--line)}
.sec::before span{display:none}
.sec-orn{display:flex;align-items:center;gap:12px;margin-bottom:1.3rem}
.sec-orn::before,.sec-orn::after{content:"";flex:1;height:1px;background:var(--line)}
.sec-orn i{font-style:normal;color:var(--madder);font-size:.85rem}
h2.sec-title{font-family:var(--disp);font-weight:400;font-size:clamp(1.6rem,3.4vw,2.3rem);letter-spacing:.01em}
.mask{display:inline-block;overflow:hidden;vertical-align:bottom}
.mask-in{display:inline-block;transform:translateY(115%);transition:transform .9s cubic-bezier(.2,.7,.2,1)}
.in .mask-in{transform:none}
.eyebrow{font-size:.62rem;letter-spacing:.3em;text-transform:uppercase;font-weight:600;color:var(--ink-soft)}

/* ---------- frontispiece ---------- */
.frontispiece{
  display:grid;grid-template-columns:340px 1fr;gap:clamp(2rem,5vw,4rem);
  padding:clamp(2.6rem,6vw,4.2rem) 0; border-bottom:1px solid var(--line);
}
.fp-figure{border:1px solid var(--ink);padding:10px;background:var(--paper2);align-self:start}
.kb{overflow:hidden}
.kb img{display:block;width:100%;height:auto;filter:sepia(.55) contrast(1.03) brightness(.98);animation:kb 22s ease-in-out infinite alternate;transform-origin:62% 38%}
@keyframes kb{to{transform:scale(1.09) translate(-1.5%,-1%)}}
.fp-figure figcaption{font-size:.66rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-soft);padding-top:10px;font-weight:600}
.lede{font-family:var(--serif);font-style:italic;font-size:1.12rem;line-height:1.65;color:var(--ink-soft);max-width:58ch}
.index{list-style:none;margin-top:1.8rem;columns:1}
.index li{
  display:flex;align-items:baseline;gap:.75rem;padding:.5rem 0;border-bottom:1px dotted rgba(34,26,16,.32);
  cursor:pointer;transition:background .3s,padding .3s;
}
.index li:hover{background:rgba(140,43,27,.06);padding-left:.45rem}
.i-no{font-family:var(--disp);color:var(--madder);min-width:2.4rem;font-size:.92rem}
.i-name{font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;font-weight:500}
.i-leaf{margin-left:auto;color:var(--madder);opacity:0;transform:translateX(-6px);transition:.3s}
.index li:hover .i-leaf{opacity:1;transform:none}

/* ---------- note on form ---------- */
.form-grid{display:grid;grid-template-columns:1fr 320px;gap:clamp(2rem,4vw,3.5rem);align-items:start}
.prose p{max-width:58ch;line-height:1.75;margin-bottom:1.1rem}
.prose p:first-child::first-letter{
  font-family:var(--disp);font-size:3.4em;float:left;line-height:.82;padding-right:.14em;color:var(--madder);
}
.gloss{margin-top:1.6rem;border-top:1px solid var(--line);padding-top:1.1rem;display:grid;gap:.7rem}
.gloss div{display:flex;gap:.8rem;font-size:.92rem;color:var(--ink-soft)}
.gloss dt{font-weight:600;color:var(--madder);min-width:7.5rem;font-size:.68rem;letter-spacing:.2em;text-transform:uppercase;padding-top:.2em}
.specimen{border:1px solid var(--ink);background:var(--paper2);padding:1.5rem;position:relative}
.specimen::before{content:"";position:absolute;inset:6px;border:1px solid var(--line);pointer-events:none}
.spec-line{font-family:var(--serif);font-size:1.3rem;margin:1rem 0 1.2rem;line-height:1.7}
.syl{display:inline-block;padding:0 1px;transition:transform .18s cubic-bezier(.2,.7,.2,1),color .18s}
.syl.stressed{position:relative}
.syl.stressed::after{content:"";position:absolute;left:12%;right:12%;bottom:-4px;height:3px;background:var(--madder);opacity:0;transition:opacity .18s}
.syl.beat{transform:scale(1.28);color:var(--madder)}
.syl.stressed.beat::after{opacity:1}
.btn{
  font-family:var(--body);font-size:.66rem;letter-spacing:.24em;text-transform:uppercase;font-weight:600;
  border:1px solid var(--ink);background:transparent;color:var(--ink);padding:.6rem 1.1rem;cursor:pointer;transition:.25s;
}
.btn:hover{background:var(--ink);color:var(--paper);transform:translate(-1px,-1px)}
.btn:active{transform:translate(1px,1px)}
.btn:disabled{opacity:.45;cursor:default}
.spec-legend{margin-top:.9rem;font-family:var(--serif);font-style:italic;font-size:.85rem;color:var(--ink-soft)}

/* ---------- reading: rail + plates ---------- */
.reading{display:grid;grid-template-columns:280px 1fr;gap:clamp(2rem,4vw,4rem);align-items:start;padding-top:2rem}
.rail{position:sticky;top:18px;max-height:calc(100vh - 36px);overflow-y:auto;padding:4px 10px 4px 2px;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.rail-ink{display:flex;align-items:center;gap:.7rem;font-size:.62rem;letter-spacing:.22em;text-transform:uppercase;font-weight:600;color:var(--ink-soft);margin-bottom:1.5rem}
.gauge{flex:1;height:5px;background:rgba(34,26,16,.12);position:relative;overflow:hidden}
.gauge i{position:absolute;inset:0;background:var(--madder);transform-origin:left;transition:transform .15s linear}
.rail-h{font-size:.66rem;letter-spacing:.28em;text-transform:uppercase;font-weight:600;color:var(--madder);margin:0 0 .8rem;display:flex;align-items:center;gap:10px}
.rail-h::after{content:"";flex:1;height:1px;background:var(--line)}
.rail-index{display:flex;flex-direction:column;border-left:1px solid var(--line);margin-bottom:2rem}
.ri{
  display:flex;gap:.6rem;align-items:baseline;padding:.36rem .7rem;background:none;border:none;
  border-left:2px solid transparent;font-family:var(--body);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;
  cursor:pointer;color:var(--ink-soft);transition:all .25s;text-align:left;
}
.rno{font-family:var(--disp);font-size:.78rem;min-width:1.8rem;transition:color .25s}
.ri-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ri:hover{color:var(--ink);transform:translateX(3px)}
.ri.on{color:var(--madder);border-left-color:var(--madder);transform:translateX(3px)}
.ri.on .rno{color:var(--madder)}
.rail-draw{border:1px solid var(--ink);background:var(--paper2);padding:1.2rem;position:relative}
.rail-draw::before{content:"";position:absolute;inset:5px;border:1px solid var(--line);pointer-events:none}
.slot{font-family:var(--disp);font-size:2.5rem;text-align:center;color:var(--madder);min-height:1.15em;letter-spacing:.05em}
.slot.rolling{animation:jolt .14s linear infinite}
@keyframes jolt{50%{transform:translateY(-3px) rotate(-2deg)}}
.stamp-btn{
  width:100%;margin-top:.9rem;font-family:var(--body);font-size:.68rem;letter-spacing:.26em;text-transform:uppercase;font-weight:600;
  background:var(--madder);color:var(--paper2);border:1px solid var(--madder);padding:.7rem;cursor:pointer;
  box-shadow:3px 3px 0 var(--ink);transition:transform .15s,box-shadow .15s;position:relative;z-index:1;
}
.stamp-btn:hover{transform:translate(-1px,-1px);box-shadow:4px 4px 0 var(--ink)}
.stamp-btn:active{transform:translate(2px,2px);box-shadow:1px 1px 0 var(--ink)}
.rail-fine{font-family:var(--serif);font-style:italic;font-size:.84rem;color:var(--ink-soft);margin-top:.9rem;text-align:center}

.plates{position:relative;min-width:0}
.plates::before{content:"";position:absolute;top:0;left:0;right:0;height:5px;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);opacity:.85}
.plate{position:relative;padding:2.5rem 0 2rem;border-top:1px solid var(--ink)}
.plate:first-child{border-top:none}
.plate::before{content:"";position:absolute;top:3px;left:0;right:0;height:1px;background:var(--ink);opacity:.35}
.plate:first-child::before{display:none}
.plate.flash::after{content:"";position:absolute;inset:-12px;border:2px solid var(--gold);animation:flash 1.1s ease-out forwards;pointer-events:none}
@keyframes flash{0%{opacity:1;transform:scale(.985)}100%{opacity:0;transform:scale(1.015)}}
.plate-head{display:flex;gap:1.4rem;align-items:baseline;margin-bottom:1.25rem}
.plate-no{
  font-family:var(--disp);font-size:clamp(2.2rem,4vw,3.3rem);color:var(--madder);line-height:1;
  min-width:2.7ch;transition:transform .45s cubic-bezier(.2,.7,.2,1);
}
.plate:hover .plate-no{transform:translateX(9px)}
.plate-title{
  font-family:var(--disp);font-weight:400;font-size:clamp(1.25rem,2.4vw,1.65rem);margin-top:.35rem;
  background-image:linear-gradient(var(--madder),var(--madder));background-repeat:no-repeat;
  background-size:0% 2px;background-position:0 97%;transition:background-size .5s cubic-bezier(.2,.7,.2,1);
}
.plate:hover .plate-title{background-size:100% 2px}
.verse{font-family:var(--serif);font-size:clamp(1.15rem,1.9vw,1.38rem);line-height:1.66;max-width:36ch}
.verse .vl{display:block}
.verse .vl:nth-child(3),.verse .vl:nth-child(4){padding-left:2.2em}
.verse .vl:last-child::after{content:" ❦";color:var(--madder);font-size:.75em}
.margin-note{
  margin-top:1.4rem;padding-top:.9rem;border-top:1px dotted rgba(34,26,16,.35);
  font-family:var(--serif);font-style:italic;color:var(--ink-soft);font-size:.97rem;max-width:62ch;
}
.note-label{font-family:var(--body);font-style:normal;font-size:.58rem;letter-spacing:.3em;text-transform:uppercase;font-weight:600;color:var(--madder);margin-right:.7rem}
.plate-foot{margin-top:1.1rem;display:flex;justify-content:flex-end}
.copy-btn{
  font-family:var(--body);font-size:.62rem;letter-spacing:.24em;text-transform:uppercase;font-weight:600;
  background:none;border:1px solid var(--line);color:var(--ink-soft);padding:.5rem 1rem;cursor:pointer;transition:.25s;
}
.copy-btn:hover{border-color:var(--ink);color:var(--ink);transform:translateY(-2px)}
.copy-btn.done{background:var(--ink);color:var(--paper);border-color:var(--ink)}

/* reveal */
.reveal{opacity:0;transform:translateY(28px) rotate(.4deg);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.reveal.in{opacity:1;transform:none}

/* ---------- interlude ---------- */
.interlude{
  margin:3.4rem 0;background:var(--ink);color:var(--paper);padding:clamp(2rem,4vw,3rem);
  display:grid;grid-template-columns:1fr 270px;gap:2.2rem;align-items:center;position:relative;
}
.interlude::before{content:"";position:absolute;inset:8px;border:1px solid rgba(242,234,214,.25);pointer-events:none}
.il-quote{font-family:var(--disp);font-weight:400;font-size:clamp(1.25rem,2.6vw,1.8rem);line-height:1.4;position:relative;padding-top:1rem}
.il-quote::before{content:"“";font-family:var(--disp);font-size:3.4rem;color:var(--gold);position:absolute;top:-.9rem;left:-.3rem}
.il-attr{margin-top:1.1rem;font-size:.62rem;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);font-weight:600}
.il-note{margin-top:1rem;font-family:var(--serif);font-style:italic;color:rgba(242,234,214,.72);font-size:.95rem;max-width:52ch}
.il-img{overflow:hidden;border:1px solid rgba(242,234,214,.35)}
.il-img img{display:block;width:100%;height:auto;filter:sepia(.45) brightness(.9);animation:kb 26s ease-in-out infinite alternate}
.il-cap{font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(242,234,214,.6);padding-top:.6rem;font-weight:600}

/* ---------- errata & colophon ---------- */
.errata-list{border-top:1px solid var(--line)}
.err{
  display:flex;gap:1.1rem;padding:1.1rem 0;border-bottom:1px dotted var(--line);
  font-family:var(--serif);font-style:italic;color:var(--ink-soft);font-size:1rem;
}
.err b{font-family:var(--disp);font-style:normal;color:var(--madder);min-width:4.2rem;font-size:.88rem;letter-spacing:.05em}
.colophon{text-align:center;padding:3.4rem 0 0}
.finis{font-family:var(--disp);font-size:clamp(1.8rem,4vw,2.6rem);color:var(--ink);margin:1.4rem 0 .4rem}
.colophon p{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-soft);font-weight:500;max-width:60ch;margin:.35rem auto}
.colophon .fl{color:var(--madder);font-size:1.3rem;display:block;margin:1.2rem 0 .2rem}

/* ---------- responsive ---------- */
@media (max-width:1020px){
  .reading{grid-template-columns:1fr}
  .rail{position:static;max-height:none;overflow:visible;display:grid;grid-template-columns:1fr 1fr;gap:1.4rem;padding:0}
  .rail-ink{grid-column:1/-1}
  .rail-index{grid-column:1/-1;display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));border-left:none;border-top:1px solid var(--line);margin-bottom:0}
  .ri{border-left:none;border-bottom:2px solid transparent}
  .ri.on{border-bottom-color:var(--madder);transform:none}
}
@media (max-width:900px){
  .frontispiece{grid-template-columns:1fr}
  .fp-figure{max-width:420px}
  .form-grid{grid-template-columns:1fr}
  .interlude{grid-template-columns:1fr}
  .il-img{max-width:360px}
}
@media (max-width:640px){
  .mast-band .b-mid{display:none}
  .stamp{width:82px;height:82px;top:20px;right:20px}
  .plate-head{gap:1rem}
  .rail{grid-template-columns:1fr}
}
/* ---------- reduced motion ---------- */
@media (prefers-reduced-motion: reduce){
  html{scroll-behavior:auto}
  .ticker-track{animation:none}
  .kb img,.il-img img,.stamp,.mast-frame{animation:none}
  .ltr{animation:none;opacity:1}
  .reveal{opacity:1;transform:none;transition:none}
  .mask-in{transform:none;transition:none}
  .plate:hover .plate-no{transform:none}
  .slot.rolling{animation:none}
}
</style>
</head>
