<main class="sheet">

  <!-- ============ FRONTISPIECE ============ -->
  <section class="frontispiece">
    <div>
      <figure class="fp-figure">
        <div class="kb"><img src="https://picsum.photos/seed/vintage-print-press/700/880" width="700" height="880" alt="An old printing press, sepia-toned"></div>
