}),{threshold:.1,rootMargin:'0px 0px -6% 0px'});
document.querySelectorAll('.reveal,.sec,.frontispiece .fp-figure').forEach(el=>io.observe(el));

const spy=new IntersectionObserver(es=>es.forEach(e=>{
