(function(){
  const bar=$('#inkbar'),g=$('#gaugeFill'),pct=$('#inkPct');let ticking=false;
  function upd(){
    const d=document.documentElement;
    const p=Math.min(1,d.scrollTop/Math.max(1,d.scrollHeight-window.innerHeight));
    bar.style.width=(p*100)+'%';
    g.style.transform=`scaleX(${1-p})`;
    pct.textContent=Math.round((1-p)*100)+'%';
    ticking=false;
  }
  window.addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(upd);}},{passive:true});
  upd();
})();

