}
.stamp-btn:hover{transform:translate(-1px,-1px);box-shadow:4px 4px 0 var(--ink)}
.stamp-btn:active{transform:translate(2px,2px);box-shadow:1px 1px 0 var(--ink)}
.rail-fine{font-family:var(--serif);font-style:italic;font-size:.84rem;color:var(--ink-soft);margin-top:.9rem;text-align:center}

.plates{position:relative;min-width:0}
