.plate{position:relative;padding:2.5rem 0 2rem;border-top:1px solid var(--ink)}
.plate:first-child{border-top:none}
.plate::before{content:"";position:absolute;top:3px;left:0;right:0;height:1px;background:var(--ink);opacity:.35}
.plate:first-child::before{display:none}
.plate.flash::after{content:"";position:absolute;inset:-12px;border:2px solid var(--gold);animation:flash 1.1s ease-out forwards;pointer-events:none}
@keyframes flash{0%{opacity:1;transform:scale(.985)}100%{opacity:0;transform:scale(1.015)}}
.plate-head{display:flex;gap:1.4rem;align-items:baseline;margin-bottom:1.25rem}
.plate-no{
