}
.note-label{font-family:var(--body);font-style:normal;font-size:.58rem;letter-spacing:.3em;text-transform:uppercase;font-weight:600;color:var(--madder);margin-right:.7rem}
.plate-foot{margin-top:1.1rem;display:flex;justify-content:flex-end}
.copy-btn{
  font-family:var(--body);font-size:.62rem;letter-spacing:.24em;text-transform:uppercase;font-weight:600;
