.il-img{overflow:hidden;border:1px solid rgba(242,234,214,.35)}
.il-img img{display:block;width:100%;height:auto;filter:sepia(.45) brightness(.9);animation:kb 26s ease-in-out infinite alternate}
.il-cap{font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(242,234,214,.6);padding-top:.6rem;font-weight:600}

/* ---------- errata & colophon ---------- */
.errata-list{border-top:1px solid var(--line)}
.err{
  display:flex;gap:1.1rem;padding:1.1rem 0;border-bottom:1px dotted var(--line);
  font-family:var(--serif);font-style:italic;color:var(--ink-soft);font-size:1rem;
}
.err b{font-family:var(--disp);font-style:normal;color:var(--madder);min-width:4.2rem;font-size:.88rem;letter-spacing:.05em}
.colophon{text-align:center;padding:3.4rem 0 0}
.finis{font-family:var(--disp);font-size:clamp(1.8rem,4vw,2.6rem);color:var(--ink);margin:1.4rem 0 .4rem}
.colophon p{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-soft);font-weight:500;max-width:60ch;margin:.35rem auto}
.colophon .fl{color:var(--madder);font-size:1.3rem;display:block;margin:1.2rem 0 .2rem}

/* ---------- responsive ---------- */
@media (max-width:1020px){
  .reading{grid-template-columns:1fr}
