{t:"Of Bill the Diver",ix:"The Diver",
 m:"The crab, on the record, “had not consented to the interview.”",
 l:["There once was a Bill who would leap and would dive,","He’d hold his breath tight — he counted to five.","He’d lift out the shell,","And he’d ask it to tell,","And he surfaced and said, “The crab, dear, would not dive.”"]},
{t:"Of Bill the Mayor",ix:"The Mayor",
 m:"The ribbon was, in the end, returned to the box, teeth-mark and all.",
 l:["There once was a Bill in a mayor’s office,","He’d sign out the orders, and sip out the coffee.","The ribbon, it was red,","And the crowd, it was led,","And he cut out the ribbon — with his teeth, at the office."]}
];

const roman=n=>ROMANS[n-1];

/* ----- masthead letter strike ----- */
(function(){
  const h=$('#mastTitle'),txt=h.textContent;h.textContent='';
  [...txt].forEach((ch,i)=>{
    const s=document.createElement('span');
    if(ch===' '){s.className='ltr sp';s.innerHTML='&nbsp;';}
    else{s.className='ltr';s.textContent=ch;if(!RM)s.style.setProperty('--d',(0.15+i*0.055)+'s');}
    s.setAttribute('aria-hidden','true');h.appendChild(s);
  });
})();

/* ----- ticker ----- */
(function(){
  const items=LIMS.map(L=>`<span><b>✦</b>&nbsp;Bill ${L.ix}</span>`).join('&nbsp;');
  $('#tickerTrack').innerHTML=`<div class="tgroup">${items}</div><div class="tgroup" aria-hidden="true">${items}</div>`;
})();

/* ----- plates ----- */
const platesWrap=$('#plates');
const inter=document.createElement('section');
inter.className='interlude reveal';
inter.innerHTML=`
  <div>
    <p class="il-quote">A limerick need not be sensible. It must, however, be punctual — the fifth line lands like a bus, and the reader, like a stop, is there when it arrives.</p>
    <p class="il-attr">— The Editor, in the margin</p>
    <p class="il-note">Here the press is oiled, the type cases re-inked, and we proceed from the thirteenth plate onward.</p>
  </div>
  <div>
    <div class="il-img"><img src="https://picsum.photos/seed/engraved-river-bridge/600/400" width="600" height="400" alt="An engraved river at dusk"></div>
    <p class="il-cap">Fig. 2 — The river at dusk; the bridge is not shown</p>
  </div>`;

(function(){
  const frag=document.createDocumentFragment();
  LIMS.forEach((L,i)=>{
    const a=document.createElement('article');
    a.className='plate reveal';a.id='plate-'+(i+1);a.dataset.i=i;
    a.style.setProperty('--d',(i%3)*0.09+'s');
    a.innerHTML=`
      <header class="plate-head">
        <span class="plate-no" aria-hidden="true">${roman(i+1)}</span>
        <div>
          <span class="eyebrow">Plate the ${ORDS[i]} · № ${String(i+1).padStart(2,'0')}</span>
          <h3 class="plate-title">${L.t}</h3>
        </div>
      </header>
      <div class="verse" aria-label="Limerick number ${i+1}">${L.l.map(x=>`<span class="vl">${x}</span>`).join('')}</div>
      <p class="margin-note"><span class="note-label">Margin</span>${L.m}</p>
      <footer class="plate-foot"><button class="copy-btn" data-i="${i}">✂ Copy the Verse</button></footer>`;
    frag.appendChild(a);
    if(i===12)frag.appendChild(inter);
  });
  platesWrap.appendChild(frag);
})();

/* ----- indexes ----- */
$('#indexList').innerHTML=LIMS.map((L,i)=>
  `<li data-i="${i}" tabindex="0" role="link"><span class="i-no">${roman(i+1)}</span><span class="i-name">Bill ${L.ix}</span><span class="i-leaf">❧</span></li>`).join('');
$('#railIndex').innerHTML=LIMS.map((L,i)=>
  `<button class="ri" data-i="${i}"><span class="rno">${roman(i+1)}</span><span class="ri-name">${L.ix}</span></button>`).join('');

function goto(i){
  const el=$('#plate-'+(i+1));
  document.querySelectorAll('.ri').forEach(b=>b.classList.toggle('on',b.dataset.i==i));
  el.scrollIntoView({behavior:RM?'auto':'smooth',block:'center'});
}
document.querySelectorAll('#indexList li').forEach(li=>{
  li.addEventListener('click',()=>goto(+li.dataset.i));
  li.addEventListener('keydown',e=>{if(e.key==='Enter')goto(+li.dataset.i)});
});
document.querySelectorAll('.ri').forEach(b=>b.addEventListener('click',()=>goto(+b.dataset.i)));

/* ----- reveals & scrollspy ----- */
const io=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}
}),{threshold:.1,rootMargin:'0px 0px -6% 0px'});
document.querySelectorAll('.reveal,.sec,.frontispiece .fp-figure').forEach(el=>io.observe(el));

const spy=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){
    const i=+e.target.dataset.i;
    document.querySelectorAll('.ri').forEach(b=>b.classList.toggle('on',b.dataset.i==i));
  }
}),{rootMargin:'-40% 0px -50% 0px'});
document.querySelectorAll('.plate').forEach(p=>spy.observe(p));

/* ----- ink gauge ----- */
(function(){
  const bar=$('#inkbar'),g=$('#gaugeFill'),pct=$('#inkPct');let ticking=false;
  function upd(){
    const d=document.documentElement;
    const p=Math.min(1,d.scrollTop/Math.max(1,d.scrollHeight-window.innerHeight));
    bar.style.width=(p*100)+'%';
    g.style.transform=`scaleX(${1-p})`;
    pct.textContent=Math.round((1-p)*100)+'%';
    ticking=false;
  }
  window.addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(upd);}},{passive:true});
  upd();
})();

/* ----- lottery ----- */
(function(){
  const slot=$('#slot'),btn=$('#drawBtn');let busy=false;
  btn.addEventListener('click',()=>{
    if(busy)return;busy=true;
    const fin=Math.floor(Math.random()*25);
    if(RM){slot.textContent=ROMANS[fin];busy=false;const pl=$('#plate-'+(fin+1));pl.classList.add('flash');setTimeout(()=>pl.classList.remove('flash'),1200);setTimeout(()=>goto(fin),150);return;}
    let i=0,ticks=16,delay=55;
    slot.classList.add('rolling');
    (function step(){
      i++;
      if(i>=ticks){
        slot.classList.remove('rolling');
        slot.textContent=ROMANS[fin];
        busy=false;
        const pl=$('#plate-'+(fin+1));
        pl.classList.add('flash');setTimeout(()=>pl.classList.remove('flash'),1200);
        setTimeout(()=>goto(fin),180);
        return;
      }
      slot.textContent=ROMANS[Math.floor(Math.random()*25)];
      delay+=7;
      setTimeout(step,delay);
    })();
  });
})();

/* ----- copy ----- */
platesWrap.addEventListener('click',e=>{
  const b=e.target.closest('.copy-btn');if(!b)return;
  const i=+b.dataset.i;
  const text=LIMS[i].t+'\n'+LIMS[i].l.join('\n');
  const done=()=>{b.classList.add('done');b.textContent='✓ In Your Pocket';
    setTimeout(()=>{b.classList.remove('done');b.textContent='✂ Copy the Verse';},1800);};
  if(navigator.clipboard){navigator.clipboard.writeText(text).then(done).catch(()=>{prompt('Copy:',text);done();});}
  else{prompt('Copy:',text);done();}
});

/* ----- scansion demo ----- */
(function(){
  const SPEC=[["There",0],["once",0],["was",1],["a",0],["Bill",1],["at",0],["a",0],["mar‑",1],["ket",0],["stall,",1]];
  const line=$('#specLine'),btn=$('#scanBtn');let running=false;
  line.innerHTML=SPEC.map(([w,s])=>`<span class="syl${s?' stressed':''}">${w}</span>`).join(' ');
  btn.addEventListener('click',()=>{
    if(running)return;running=true;btn.disabled=true;
    const syls=[...line.querySelectorAll('.syl')];
    syls.forEach((t,idx)=>setTimeout(()=>{
      t.classList.add('beat');
      setTimeout(()=>t.classList.remove('beat'),280);
    },idx*(RM?60:170)));
    setTimeout(()=>{running=false;btn.disabled=false;},syls.length*(RM?60:170)+500);
  });
})();
})();
</script>
</body>
</html>
```

**Highlights:** a Victorian "broadside" masthead with letter-by-letter type strike and a rotating approval stamp, a running ticker of all 25 Bills, an index with dotted leaders, 25 fully-rhymed AABBA limericks (one with the **economist**, one with **Jurgen**), marginalia under each verse, a "Draw a Bill" lottery with a decelerating slot, a draining ink gauge, a clickable anapest scansion demo, and an errata page that dutifully explains the lowercase *bill*. All motion respects `prefers-reduced-motion`.

